/**
 * Tid & vardagsrutiner, 401–407 (0.20): clocks, calendars and time lines. Clock words are shown on an
 * analog clock with the named part of the hour shaded; calendar words on a calendar with today marked.
 * Digits are allowed (they never spell the word); weekday and month names are not written out.
 */
import { C, all, arrow, circle, ellipse, g, line, path, rect, sparkle, star, type Svg } from './kit';
import { HL, arm, bubble, heart, sun } from './people';
