const ground = line('M4 112 L116 112', C.grey2, 2);
const pt = (x: number, y: number, r: number, deg: number) => [x + Math.sin((deg * Math.PI) / 180) * r, y - Math.cos((deg * Math.PI) / 180) * r] as const;
const f1 = (n: number) => n.toFixed(1);
/** Shaded sector of a clock from minute a to minute b (clockwise). */
const sector = (x: number, y: number, r: number, a: number, b: number, col: string) => {
  const [x1, y1] = pt(x, y, r, a * 6), [x2, y2] = pt(x, y, r, b * 6);
  return path(`M${x} ${y} L${f1(x1)} ${f1(y1)} A${r} ${r} 0 ${b - a > 30 ? 1 : 0} 1 ${f1(x2)} ${f1(y2)} Z`, col, null);
};
/** Analog clock showing h:m; optional shaded minute range and numbers. */
export function clock(x: number, y: number, r: number, h: number, m: number, o: { shade?: [number, number]; shadeCol?: string; face?: string; nums?: boolean; rim?: string } = {}): Svg {
  const out: Svg[] = [circle(x, y, r + 3, o.rim ?? C.dark, C.ink, 1.8), circle(x, y, r, o.face ?? C.white, C.ink, 1.2)];
  if (o.shade) out.push(sector(x, y, r - 1, o.shade[0], o.shade[1], o.shadeCol ?? 'rgba(228,87,46,0.35)'));
  for (let i = 0; i < 12; i++) { const [a1, b1] = pt(x, y, r * 0.86, i * 30), [a2, b2] = pt(x, y, r * (i % 3 ? 0.94 : 0.78), i * 30); out.push(line(`M${f1(a1)} ${f1(b1)} L${f1(a2)} ${f1(b2)}`, C.ink, i % 3 ? 1 : 1.8)); }
  if (o.nums) for (const n of [12, 3, 6, 9]) { const [a, b] = pt(x, y, r * 0.62, n * 30); out.push(`<text x="${f1(a)}" y="${f1(b + r * 0.1)}" font-family="system-ui" font-weight="700" font-size="${f1(r * 0.28)}" text-anchor="middle" fill="${C.ink}">${n}</text>`); }
  const [hx, hy] = pt(x, y, r * 0.5, ((h % 12) + m / 60) * 30), [mx, my] = pt(x, y, r * 0.8, m * 6);
  out.push(line(`M${x} ${y} L${f1(hx)} ${f1(hy)}`, C.ink, Math.max(2, r * 0.1)), line(`M${x} ${y} L${f1(mx)} ${f1(my)}`, C.ink, Math.max(1.4, r * 0.06)), circle(x, y, Math.max(1.6, r * 0.07), C.accent, null));
  return all(...out);
}
/** Digital display. */
export const digi = (x: number, y: number, txt: string, w = 40, col = '#7ef0a0') => all(rect(x - w / 2, y - 10, w, 20, C.black, 4, C.ink, 1.6), `<text x="${x}" y="${y + 5}" font-family="ui-monospace,monospace" font-weight="700" font-size="14" text-anchor="middle" fill="${col}">${txt}</text>`);
/** Calendar sheet with rows × 7 day cells; `cell(i)` returns a fill colour (or null for plain). */
export function cal(x: number, y: number, w: number, rows: number, cell: (i: number) => string | null = () => null, o: { head?: string; mark?: (i: number) => Svg } = {}): Svg {
  const cw = (w - 8) / 7, ch = cw * 0.9, h = 14 + rows * (ch + 2) + 4;
  const out: Svg[] = [rect(x, y, w, h, C.white, 4, C.ink, 1.8), rect(x, y, w, 10, o.head ?? '#e85a5a', 4, C.ink, 1.8), circle(x + w * 0.3, y, 2, C.dark, null), circle(x + w * 0.7, y, 2, C.dark, null)];
  for (let i = 0; i < rows * 7; i++) {
    const cx = x + 4 + (i % 7) * cw, cy = y + 14 + Math.floor(i / 7) * (ch + 2);
    out.push(rect(cx + 0.6, cy, cw - 1.2, ch, cell(i) ?? (i % 7 >= 5 ? '#fbe4e4' : '#f2f0ea'), 1.4, C.grey2, 0.6));
    if (o.mark) out.push(g(`translate(${f1(cx + cw / 2)} ${f1(cy + ch / 2)})`, o.mark(i)));
  }
  return all(...out);
}
/** Geometry of a calendar cell centre (same layout as cal). */
export const cellAt = (x: number, y: number, w: number, i: number) => { const cw = (w - 8) / 7, ch = cw * 0.9; return [x + 4 + (i % 7) * cw + cw / 2, y + 14 + Math.floor(i / 7) * (ch + 2) + ch / 2] as const; };
