const flagSE = (x: number, y: number, s = 1) => g(`translate(${x} ${y}) scale(${s})`, line('M0 0 L0 -24', C.ink, 1.6), rect(0, -24, 16, 10, '#3a6ab0', 0, C.ink, 1), rect(5, -24, 3, 10, C.yellow, 0, null), rect(0, -20.5, 16, 3, C.yellow, 0, null));
