const phoneB = (x: number, y: number, s = 1, inner: Svg = '') => g(`translate(${x} ${y}) scale(${s})`, rect(-14, -24, 28, 48, C.dark, 4, C.ink, 1.8), rect(-11, -19, 22, 36, '#eaf4fb', 1.4, null), inner);
const tree0 = (x: number, y: number) => all(rect(x - 2, y - 12, 4, 12, C.brown, 1, C.ink, 1), circle(x, y - 18, 9, C.green, C.ink, 1.2));
